INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (366463, 15226, 'South China Morning Post', 'en', 'Why Siberia’s warming landscape could shatter Trump’s Arctic ambitions', 'https://www.scmp.com/news/china/science/article/3364286/why-siberias-warming-landscape-could-shatter-trumps-arctic-ambitions', 'As the United States, Russia and China race to turn a melting Arctic into the world’s next major economic gateway, their strategic ambitions face a hidden threat: thawing permafrost. Since returning to office last year, US President Donald Trump has pushed to expand America’s Arctic footprint. This includes investing in icebreakers to counter Russian and Chinese shipping ambitions, unlocking natural resources in Alaska and renewing efforts to buy or annex Greenland. Yet, as the three powers vie...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/17/02ca88ea-b760-441b-ae91-4d6608c4eb40_dd4b49e6.jpg?itok=uSDXHxJo&v=1786956809', '2026-08-18T02:00:17+00:00', '2026-08-18T03:12:26.927535'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (366465, 15226, 'South China Morning Post', 'en', 'Trump’s decision to scale back South Korea drills unsettles Asian allies: ‘makes no sense’', 'https://www.scmp.com/news/asia/east-asia/article/3364352/trumps-decision-scale-back-south-korea-drills-unsettles-asian-allies-makes-no-sense', 'President Donald Trump’s decision to scale back joint military exercises with South Korea does not just slight a long-time ally but raises broader concerns about the security interests of the United States in Asia and elsewhere. Trump explained his decision by citing South Korea’s refusal to join his war against Iran and pointing to what he said was his good relationship with North Korea’s reclusive dictator Kim Jong-un, a transactional and personal approach to foreign policy that has defined...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/18/c895d744-13cd-45cc-97b3-bb391e8db36c_8241b58f.jpg?itok=1ym-IHLX&v=1787016733', '2026-08-18T01:32:23+00:00', '2026-08-18T03:12:26.948141'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
