INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (368281, 15237, 'The Times of India', 'en', 'Hockey World Cup qualification scenarios: What India need vs Pakistan', 'https://timesofindia.indiatimes.com/sports/hockey/top-stories/indias-hockey-world-cup-2026-qualification-scenarios-what-india-need-against-pakistan/articleshow/133311817.cms', 'India have to beat or draw against Pakistan to keep their hopes of reaching the second round alive. England are currently top of Pool D with six points. India are second with three points, while Pakistan and Wales have one point each after two matches. The top two teams from each pool will move into the second round. The bottom two teams will play in the 9th-16th classification matches. India had started their campaign with a 3-1 win over Wales.', 'https://static.toiimg.com/photo/msid-133312017,imgsize-77880.cms', '2026-08-18T04:55:00+00:00', '2026-08-18T05:44:28.000091'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
